// danmu_api/configs/handlers/handler-factory.js
var HandlerFactory = class {
  static async getHandler(deployPlatform) {
    switch (deployPlatform?.toLowerCase()) {
      case "cloudflare":
        const { CloudflareHandler: CloudflareHandler2 } = await Promise.resolve().then(() => (init_cloudflare_handler(), cloudflare_handler_exports));
        return new CloudflareHandler2();
      case "vercel":
        const { VercelHandler: VercelHandler2 } = await Promise.resolve().then(() => (init_vercel_handler(), vercel_handler_exports));
        return new VercelHandler2();
      case "netlify":
        const { NetlifyHandler: NetlifyHandler2 } = await Promise.resolve().then(() => (init_netlify_handler(), netlify_handler_exports));
        return new NetlifyHandler2();
      case "edgeone":
        const { EdgeoneHandler: EdgeoneHandler2 } = await Promise.resolve().then(() => (init_edgeone_handler(), edgeone_handler_exports));
        return new EdgeoneHandler2();
      case "huggingface":
        const { HuggingfaceHandler: HuggingfaceHandler2 } = await Promise.resolve().then(() => (init_huggingface_handler(), huggingface_handler_exports));
        return new HuggingfaceHandler2();
      case "node":
        const { NodeHandler } = await import(["./node-handler", ".js"].join(""));
        return new NodeHandler();
      default:
        const { NodeHandler: DefaultNodeHandler } = await import(["./node-handler", ".js"].join(""));
        return new DefaultNodeHandler();
    }
  }
  /**
   * 获取所有支持的平台列表
   */
  static getSupportedPlatforms() {
    return ["cloudflare", "vercel", "netlify", "edgeone", "huggingface", "node"];
  }
};

